package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(in, &n, &m)
	N := n * m

	// Enumerate cells
	type Cell struct{ r, c int }
	cells := make([]Cell, 0, N)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			cells = append(cells, Cell{i, j})
		}
	}

	// Precompute neighbors (including staying)
	neighbors := make([][]int, N)
	for idx, cell := range cells {
		r, c := cell.r, cell.c
		var ns []int
		ns = append(ns, idx) // stay
		if r > 0 {
			ns = append(ns, (r-1)*m+c)
		}
		if r+1 < n {
			ns = append(ns, (r+1)*m+c)
		}
		if c > 0 {
			ns = append(ns, r*m+(c-1))
		}
		if c+1 < m {
			ns = append(ns, r*m+(c+1))
		}
		neighbors[idx] = ns
	}

	maxFree := 0
	totalMasks := 1 << N

	// For each subset of empty cells
	for mask := 0; mask < totalMasks; mask++ {
		occupiedCount := N - bitsCount(mask)
		if occupiedCount <= maxFree {
			continue
		}
		// Build bipartite graph: spiders (left) -> target cells (right)
		adj := make([][]int, N)
		for i := 0; i < N; i++ {
			if (mask>>i)&1 != 0 {
				continue // cell i is empty, no spider
			}
			for _, to := range neighbors[i] {
				if (mask>>to)&1 == 0 { // target must be occupied cell
					adj[i] = append(adj[i], to)
				}
			}
		}

		// Maximum bipartite matching
		matchR := make([]int, N)
		for i := range matchR {
			matchR[i] = -1
		}

		var dfs func(int, []bool) bool
		dfs = func(v int, used []bool) bool {
			for _, to := range adj[v] {
				if used[to] {
					continue
				}
				used[to] = true
				if matchR[to] == -1 || dfs(matchR[to], used) {
					matchR[to] = v
					return true
				}
			}
			return false
		}

		matched := 0
		for i := 0; i < N; i++ {
			if (mask>>i)&1 != 0 {
				continue
			}
			used := make([]bool, N)
			if dfs(i, used) {
				matched++
			}
		}

		if matched == occupiedCount {
			if N-occupiedCount > maxFree {
				maxFree = N - occupiedCount
			}
		}
	}

	fmt.Println(maxFree)
}

func bitsCount(x int) int {
	// simple popcount for small N (<=40)
	cnt := 0
	for x > 0 {
		cnt += x & 1
		x >>= 1
	}
	return cnt
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	to   int
	rev  int
	cap  int
}

type Dinic struct {
	n     int
	g     [][]Edge
	level []int
	it    []int
}

func NewDinic(n int) *Dinic {
	return &Dinic{
		n:     n,
		g:     make([][]Edge, n),
		level: make([]int, n),
		it:    make([]int, n),
	}
}

func (d *Dinic) addEdge(from, to, cap int) {
	fwd := Edge{to: to, rev: len(d.g[to]), cap: cap}
	rev := Edge{to: from, rev: len(d.g[from]), cap: 0}
	d.g[from] = append(d.g[from], fwd)
	d.g[to] = append(d.g[to], rev)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (d *Dinic) bfs(s, t int) bool {
	for i := range d.level {
		d.level[i] = -1
	}
	queue := []int{s}
	d.level[s] = 0
	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		for _, e := range d.g[v] {
			if e.cap > 0 && d.level[e.to] < 0 {
				d.level[e.to] = d.level[v] + 1
				queue = append(queue, e.to)
			}
		}
	}
	return d.level[t] >= 0
}

func (d *Dinic) dfs(v, t, f int) int {
	if v == t {
		return f
	}
	for ; d.it[v] < len(d.g[v]); d.it[v]++ {
		ei := d.it[v]
		e := &d.g[v][ei]
		if e.cap > 0 && d.level[v] < d.level[e.to] {
			delta := d.dfs(e.to, t, min(f, e.cap))
			if delta > 0 {
				e.cap -= delta
				re := &d.g[e.to][e.rev]
				re.cap += delta
				return delta
			}
		}
	}
	return 0
}

func (d *Dinic) maxFlow(s, t int) int {
	flow := 0
	for d.bfs(s, t) {
		for i := range d.it {
			d.it[i] = 0
		}
		for {
			f := d.dfs(s, t, 1<<30)
			if f == 0 {
				break
			}
			flow += f
		}
	}
	return flow
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(in, &n, &m)

	total := n * m
	if total == 0 {
		fmt.Println(0)
		return
	}

	// Directions: stay, up, down, left, right
	dirs := [][2]int{{0, 0}, {-1, 0}, {1, 0}, {0, -1}, {0, 1}}

	// Precompute possible moves for each cell
	type Move struct {
		to int
	}
	moves := make([][]Move, total)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			id := i*m + j
			for _, d := range dirs {
				ni, nj := i+d[0], j+d[1]
				if ni >= 0 && ni < n && nj >= 0 && nj < m {
					to := ni*m + nj
					moves[id] = append(moves[id], Move{to})
				}
			}
		}
	}

	// Build bipartite graph: left side = spiders (one per cell), right side = cells
	// Edge from spider s to cell c if spider at cell s can move/stay to cell c
	// We want maximum matching size = maximum number of occupied cells
	// Answer = total cells - maximum matching
	S := total * 2
	T := S + 1
	dinic := NewDinic(T + 1)

	// Left nodes: 0..total-1 (spiders)
	// Right nodes: total..2*total-1 (cells)
	for s := 0; s < total; s++ {
		dinic.addEdge(S, s, 1)
	}
	for c := 0; c < total; c++ {
		dinic.addEdge(total+c, T, 1)
	}

	for s := 0; s < total; s++ {
		for _, mv := range moves[s] {
			c := mv.to
			dinic.addEdge(s, total+c, 1)
		}
	}

	maxMatching := dinic.maxFlow(S, T)
	ans := total - maxMatching
	fmt.Println(ans)
}

