		to int
	}
	// map cell (i,j) to id
	id := make([][]int, n)
	for i := 0; i < n; i++ {
		id[i] = make([]int, m)
	}
	blackCount, whiteCount := 0, 0
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if (i+j)%2 == 0 {
				id[i][j] = blackCount
				blackCount++
			} else {
				id[i][j] = whiteCount
				whiteCount++
			}
		}
	}

	adj := make([][]int, blackCount)
	dirs := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if (i+j)%2 != 0 {
				continue
			}
			u := id[i][j]
			for _, d := range dirs {
				ni, nj := i+d[0], j+d[1]
				if ni >= 0 && ni < n && nj >= 0 && nj < m {
					v := id[ni][nj]
					adj[u] = append(adj[u], v)
				}
			}
		}
	}

	// Maximum bipartite matching (Kuhn)
	matchR := make([]int, whiteCount)
	for i := range matchR {
		matchR[i] = -1
	}
	var used []bool
	var dfs func(int) bool
	dfs = func(v int) bool {
		for _, to := range adj[v] {
			if used[to] {
				continue
			}
			used[to] = true
			if matchR[to] == -1 || dfs(matchR[to]) {
				matchR[to] = v
				return true
			}
		}
		return false
	}

	matching := 0
	for v := 0; v < blackCount; v++ {
		used = make([]bool, whiteCount)
		if dfs(v) {
			matching++
		}
	}

	// Each matched edge can host 2 spiders; unmatched cells host 1
	occupied := 2*matching + (total - 2*matching)
	// But we can place at most one spider per cell initially; after movement,
	// each matched pair can be merged into one cell, freeing one cell.
	// So maximum free cells = matching
	// However, total cells - occupied after merging:
	// occupied after merging = total - matching
	// free = matching
	freeCells := matching
	fmt.Println(freeCells)
