			if (i+j)%2 == 0 {
				addEdge(S, v, 1)
				for _, d := range dirs {
					ni, nj := i+d[0], j+d[1]
					if ni >= 0 && ni < n && nj >= 0 && nj < m {
						u := id(ni, nj)
						addEdge(v, u, 1)
					}
				}
			} else {
				addEdge(v, T, 1)
			}
		}
	}

	level := make([]int, N+2)
	it := make([]int, N+2)

	var bfs func() bool
	bfs = func() bool {
		for i := range level {
			level[i] = -1
		}
		queue := []int{S}
		level[S] = 0
		for len(queue) > 0 {
			v := queue[0]
			queue = queue[1:]
			for _, e := range graph[v] {
				if e.cap > 0 && level[e.to] < 0 {
					level[e.to] = level[v] + 1
					queue = append(queue, e.to)
				}
			}
		}
		return level[T] >= 0
	}

	var dfs func(int, int) int
	dfs = func(v, f int) int {
		if v == T {
			return f
		}
		for ; it[v] < len(graph[v]); it[v]++ {
			e := &graph[v][it[v]]
			if e.cap > 0 && level[v] < level[e.to] {
				d := dfs(e.to, min(f, e.cap))
				if d > 0 {
					e.cap -= d
					graph[e.to][e.rev].cap += d
					return d
				}
			}
		}
		return 0
	}

	flow := 0
	for bfs() {
		for i := range it {
			it[i] = 0
		}
		for {
			f := dfs(S, 1<<30)
			if f == 0 {
				break
			}
			flow += f
		}
	}

	fmt.Println(N - flow)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(in, &n, &m)
	N := n * m

	// Map cell (i,j) to index
	id := func(i, j int) int {
		return i*m + j
	}

	// Precompute neighbors for each cell
	type Cell struct{ x, y int }
	cells := make([]Cell, N)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			cells[id(i, j)] = Cell{i, j}
		}
	}

	neighbors := make([][]int, N)
	for idx := 0; idx < N; idx++ {
		i, j := cells[idx].x, cells[idx].y
		ns := []int{idx} // staying
		if i > 0 {
			ns = append(ns, id(i-1, j))
		}
		if i+1 < n {
			ns = append(ns, id(i+1, j))
		}
		if j > 0 {
			ns = append(ns, id(i, j-1))
		}
		if j+1 < m {
			ns = append(ns, id(i, j+1))
		}
		neighbors[idx] = ns
	}

	best := 0
	// Enumerate all assignments: for each cell choose one neighbor index
	// We encode assignment as mixed radix counter: for cell i, base = len(neighbors[i])
	// We'll iterate via recursion or iterative increment.

	// Precompute bases
	bases := make([]int, N)
	for i := 0; i < N; i++ {
		bases[i] = len(neighbors[i])
	}

	assign := make([]int, N) // current choice indices

	for {
		// compute occupied cells bitmask
		var mask uint64 = 0
		for i := 0; i < N; i++ {
			dest := neighbors[i][assign[i]]
			mask |= 1 << uint(dest)
		}
		// count bits
		occupied := bitsCount(mask)
		free := N - occupied
		if free > best {
			best = free
		}

		// increment mixed radix counter
		pos := 0
		for pos < N {
			assign[pos]++
			if assign[pos] < bases[pos] {
				break
			}
			assign[pos] = 0
			pos++
		}
		if pos == N {
			break
		}
	}

	fmt.Println(best)
}

func bitsCount(x uint64) int {
	// builtin if available; otherwise manual
	// Go has bits.OnesCount64, but to avoid importing math/bits, implement simple popcount
	x = x - ((x >> 1) & 0x5555555555555555)
	x = (x & 0x3333333333333333) + ((x >> 2) & 0x3333333333333333)
	x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0f
	x = x + (x >> 8)
	x = x + (x >> 16)
	x = x + (x >> 32)
	return int(x & 0x7f)
}
